/** A reviewed project of two primaries joined by ' & ', a featured entry and a label, on two discs, with a hidden reused Artist. */
function reviewed() {
  const item = detail(); item.publication = 'notStarted'; item.capabilities.publish = true; item.revision = 4;
  item.draft.album = { title: 'Synthetic Album', artists: [{ ...artistEntry('Lorem'), joinPhrase: ' & ' }, artistEntry('Ipsum', entryKey(2)), artistEntry('Dolor', entryKey(3), 'featured')], label: labelEntry('Sit Records'), releaseDate: { year: 2026, month: 3, day: null }, visibility: 'hidden' };
  item.draft.tracks = [{ slotId, title: 'Second Disc Opening', discNumber: 2, trackNumber: 1 }, { slotId: slotTwo, title: 'First Disc Opening', discNumber: 1, trackNumber: 1 }];
  item.assets = [{ slotId: 'cover', state: 'ready', byteLength: 100, sha256: 'b'.repeat(64), contentType: 'image/png', tags: null, recovery: null }]; item.selectedCoverSlotId = 'cover';
  const ipsum: ImportCandidate = { kind: 'artist', id: '1'.repeat(24), label: 'Ipsum', revision: 'r-ipsum', albumId: null, visibility: 'hidden', match: 'name', matchedSlotIds: [], automaticReuse: false };
  const fresh = { action: 'create-distinct', candidateId: null, candidateRevision: null } as const;
  item.decisions = [{ scope: 'artist', slotId: null, entryKey: entryKey(1), boundName: 'Lorem', ...fresh }, { scope: 'artist', slotId: null, entryKey: entryKey(2), boundName: 'Ipsum', action: 'reuse', candidateId: ipsum.id, candidateRevision: ipsum.revision },
    { scope: 'artist', slotId: null, entryKey: entryKey(3), boundName: 'Dolor', ...fresh }, { scope: 'label', slotId: null, entryKey: null, boundName: 'Sit Records', ...fresh }, ...distinct()];
  return { item, ipsum };
}
const candidatesEndpoint = (items: ImportCandidate[], reads: string[] = []) => vi.fn(async (path: string) => { reads.push(path); return json({ items, memberMatchesComplete: true }); });

